'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{chromium}=require('playwright'),{parse}=require('../audits/audit-i18n-global.cjs');
const root=process.env.CONFIRMATION_ADRESSE_ASSET_DIR||path.resolve(__dirname,'../..'),read=f=>fs.readFileSync(path.join(root,f),'utf8');
function functions(s){return parse(s).body.filter(n=>n.type==='FunctionDeclaration'&&['rpRetourConfirmation','ouvrirConnexionCompte','rafraichirEcranCreationApresChangementLangue'].includes(n.id.name)).map(n=>s.slice(n.start,n.end)).join('\n');}
const locales=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'];
test('confirmation : 108 arrivées et 972 bascules, neuf langues, 320/390/1280, sans authentification ni perte de saisie',async()=>{
 const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});
 try{for(const width of [320,390,1280]){const page=await browser.newPage({viewport:{width,height:800}}),errors=[];page.on('pageerror',e=>errors.push(String(e)));await page.route('**/*',r=>r.fulfill({contentType:'text/html',body:read('index.html').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,'')}));await page.goto('https://fixture.invalid/index.html');await page.addStyleTag({content:read('style.css')});
 await page.evaluate(()=>{document.body.insertAdjacentHTML('afterbegin','<input id="audit-draft" value="Brouillon conservé">');window.calls=[];for(const name of ['fetch','rpAuthSeConnecter','sbRpc','sbLoadPersonnage','rpAssurerSessionAnonyme'])window[name]=(...a)=>{calls.push(name);throw Error('Appel métier interdit');};window.state={pa:20,arg:200,progression:{stage:2}};window.snapshot=()=>JSON.stringify({calls,state,hash:location.hash,history:history.length,session:JSON.stringify(sessionStorage),storage:Object.fromEntries(Object.entries(localStorage).filter(([k])=>!k.includes('lang'))),draft:document.getElementById('audit-draft').value,email:document.getElementById('connexion-email').value,password:document.getElementById('connexion-mdp').value,panel:document.getElementById('connexion-panel').style.display,focus:document.activeElement.id,start:document.getElementById('connexion-mdp').selectionStart,end:document.getElementById('connexion-mdp').selectionEnd});});
 for(const f of ['i18n/i18next.min.js','i18n/resources.js','i18n/connection-resources.js','i18n/i18n-init.js'])await page.addScriptTag({content:read(f)});await page.addScriptTag({content:'let _currentScreenIndex=0;\n'+functions(read('creation.js'))+'\nwindow.RP_I18N_ON_LANGUAGE_CHANGE=rafraichirEcranCreationApresChangementLangue;'});
 for(const scenario of ['expired','closed','open','foreign'])for(const initial of locales){const before=await page.evaluate(async({scenario,initial})=>{changerLangueRP(initial);const panel=document.getElementById('connexion-panel');panel.style.display=scenario==='open'?'block':'none';document.getElementById('retour-confirmation').innerHTML='';document.getElementById('connexion-email').value='fixture@example.invalid';document.getElementById('connexion-mdp').value='mot-de-passe-fictif';sessionStorage.setItem('fixture','conservé');history.replaceState(null,'',scenario==='foreign'?'#ancre-etrangere':scenario==='expired'?'#error_code=otp_expired':'#type=signup&access_token=fixture-invalid');rpRetourConfirmation();document.getElementById(panel.style.display==='block'?'connexion-mdp':'audit-draft').focus();document.getElementById('connexion-mdp').setSelectionRange(2,6);return {snapshot:snapshot(),hash:location.hash,panel:panel.style.display};},{scenario,initial});assert.equal(before.hash,scenario==='foreign'?'#ancre-etrangere':'');assert.equal(before.panel,['open','closed'].includes(scenario)?'block':'none');
 for(const lang of locales){const got=await page.evaluate(({lang,scenario})=>{changerLangueRP(lang);return {same:snapshot(),rows:[...document.querySelectorAll('#retour-confirmation [data-i18n]')].map(n=>({actual:n.textContent,expected:i18next.t(n.dataset.i18n),dir:n.dir})),overflow:document.documentElement.scrollWidth>innerWidth};},{lang,scenario});assert.equal(got.same,before.snapshot);assert.equal(got.rows.length,scenario==='foreign'?0:2);for(const row of got.rows){assert.equal(row.actual,row.expected);assert.equal(row.dir,lang==='ar'?'rtl':'');}assert.equal(got.overflow,false,scenario+'/'+lang+'/'+width);}}
 // Missing translation: the existing French fallback applies without reopening a panel or parsing the URL again.
 await page.evaluate(()=>{history.replaceState(null,'','#error_code=otp_expired');changerLangueRP('fr');rpRetourConfirmation();const d=i18next.getResourceBundle('de','translation');delete d.connectionUi.confirmationExpiredBody;i18next.removeResourceBundle('de','translation');i18next.addResourceBundle('de','translation',d);changerLangueRP('de');});assert.equal(await page.locator('[data-i18n="connectionUi.confirmationExpiredBody"]').textContent(),await page.evaluate(()=>RP_I18N_RESOURCES.fr.translation.connectionUi.confirmationExpiredBody));
 assert.deepEqual(await page.evaluate(()=>calls),[]);assert.deepEqual(errors,[]);await page.close();}}finally{await browser.close();}
});
